sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float yaw;
uniform float pitch;
uniform float roll;
float3 turn(float3 d) {
    float y = radians(yaw);
    float p = radians(pitch);
    float r = radians(roll);
    d = float3(cos(r) * d.x - sin(r) * d.y, sin(r) * d.x + cos(r) * d.y, d.z);
    d = float3(d.x, cos(p) * d.y - sin(p) * d.z, sin(p) * d.y + cos(p) * d.z);
    return float3(cos(y) * d.x + sin(y) * d.z, d.y, -sin(y) * d.x + cos(y) * d.z);
}
half4 panorama(float3 d) {
    float lon = atan(d.x, d.z);
    float lat = asin(clamp(d.y, -1.0, 1.0));
    float2 uv = float2(lon / 6.2831853 + 0.5, 0.5 - lat / 3.1415927);
    float2 at = float2(mod(uv.x * size.x, size.x), clamp(uv.y * size.y, 0.5, size.y - 0.5));
    return image.eval(clamp(at, float2(0.5), size - 0.5));
}
half4 main(float2 coord) {
    float2 uv = coord / size;
    float lon = (uv.x - 0.5) * 6.2831853;
    float lat = (0.5 - uv.y) * 3.1415927;
    float3 d = float3(cos(lat) * sin(lon), sin(lat), cos(lat) * cos(lon));
    if (coord.x < 0.0 || coord.y < 0.0 || coord.x > size.x || coord.y > size.y) return half4(0.0);
    return panorama(turn(d));
}
